const field = (rhs, initial, exact = '') => ({rhs, initial, exact});
const base = {dimension: 1, N: 128, Lx: 2 * Math.PI, Ly: 2 * Math.PI, T: 2, dt: .02, frames: 61, parameters: '', boundary: 'periodic'};
const edge=(type,value='0')=>({type,value});
const walls=(type,value='0')=>Object.fromEntries(['left','right','bottom','top'].map(s=>[s,edge(type,value)]));
const bounded={...base,boundary:'nonperiodic',N:64,Lx:1,Ly:1,T:1,dt:.005,parameters:'nu = 0.1'};
const condition=(order,value='0')=>({coefficients:[0,1,2,3].map(k=>k===order?'1':'0'),value});
const pair=(a,b,va='0',vb='0')=>({conditions:[condition(a,va),condition(b,vb)]});
const fourth={...bounded,boundary:'fourth-order',N:64,T:.3,dt:.001,parameters:'kappa=0.01'};
const front=z=>`((1+tanh((${z})/2))/2)^1.5`;
const slope=z=>`1.5*(${front(z)})*(1-(1+tanh((${z})/2))/2)`;
const maeParameters='gamma=-1; beta=-15/2; alpha=-71/4; a=0; b=315/16; c=105/8';
const maeRhs='gamma*Dx(u,4)-beta*Dx(u,3)+alpha*Dx(u,2)-Dx(a*u^2+2*b*u^3/3,1)';
